127	__aicore__ inline void ScatterBlockUpdateKernel<T, IndexT>::CopyIn(
128	    int64_t startIdx, int64_t loadCount)
129	{
130	    LocalTensor<IndexT> indLocal = indicesQue_.AllocTensor<IndexT>();
131	    LocalTensor<T> updLocal = updateQue_.AllocTensor<T>();
