133	    // 加载indices: loadCount行 × 2列, GM中连续存储, 整块32B对齐搬运
134	    int64_t indBytes = loadCount * INDICES_LAST_DIM * static_cast<int64_t>(sizeof(IndexT));
135	    DataCopyExtParams indicesCopyParams;
136	    indicesCopyParams.blockCount = 1;
137	    indicesCopyParams.blockLen = static_cast<uint32_t>(indBytes);
138	    indicesCopyParams.srcStride = 0;
139	    indicesCopyParams.dstStride = 0;
140	    DataCopyPadExtParams<IndexT> indicesPadParams{false, 0, 0, 0};
141	    DataCopyPad(indLocal, indicesGm_[startIdx * INDICES_LAST_DIM], indicesCopyParams, indicesPadParams);
142	
143	    // 加载updates
144	    // 用DataCopyPad按行加载, 每行在UB中padding到oneUpdateAlignSize_字节
145	    // 保证ScatterOut中 updLocal[i * updateRowElements_] 取子视图时偏移32B对齐
146	    DataCopyExtParams copyParams;
147	    copyParams.blockCount = static_cast<uint16_t>(loadCount);
148	    copyParams.blockLen = static_cast<uint32_t>(updateDimSize_ * static_cast<int64_t>(sizeof(T)));
149	    copyParams.srcStride = 0;  // GM中行连续, 无间隔
150	    copyParams.dstStride = 0;  // UB行间padding
151	    DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
152	    DataCopyPad(updLocal, updateGm_[startIdx * updateDimSize_], copyParams, padParams);
153	
154	    indicesQue_.EnQue(indLocal);
155	    updateQue_.EnQue(updLocal);
156	}
