171	        IndexT idx1 = indLocal.GetValue(static_cast<uint32_t>(i * INDICES_LAST_DIM + 1));
172	        if (idx0 < 0 || idx1 < 0) {
173	            continue;
174	        }
175	        // 根据stride计算GM中目标行的元素偏移
176	        // offset = idx0 * stride0 + idx1 * stride1
177	        int64_t gmOffset = static_cast<int64_t>(idx0) * inputStride0_ +
178	                           static_cast<int64_t>(idx1) * inputStride1_;
