/*!
 * \file ai_infra_scatter_block_update.h
 * \brief AiInfraScatterBlockUpdate kernel implementation.
 *        Formula: input[indices[k,0], indices[k,1], :] = update[k, :]
 *        Supports non-contiguous input tensor on dim 0 via stride.
 */

#ifndef __AI_INFRA_SCATTER_BLOCK_UPDATE_KERNEL_H__
#define __AI_INFRA_SCATTER_BLOCK_UPDATE_KERNEL_H__

#include "kernel_operator.h"

using namespace AscendC;

constexpr int32_t SCATTER_BUF_NUM = 2;
constexpr int32_t INDICES_LAST_DIM = 2;
constexpr int64_t THIRTY_ONE = 31;

template <typename T, typename IndexT>
class ScatterBlockUpdateKernel {
public:
    template <typename TilingDataT>
    __aicore__ inline void Init(GM_ADDR input, GM_ADDR indices, GM_ADDR update,
                                const TilingDataT& tiling, TPipe* pipe);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t startIdx, int64_t loadCount);
    __aicore__ inline void ScatterOut(int64_t loadCount);

    GlobalTensor<T> inputGm_;
    GlobalTensor<IndexT> indicesGm_;
    GlobalTensor<T> updateGm_;

    TQue<TPosition::VECIN, SCATTER_BUF_NUM> indicesQue_;
    TQue<TPosition::VECIN, SCATTER_BUF_NUM> updateQue_;
    TPipe* pipe_;

    int64_t updateDimSize_;
    int64_t eachCoreIndexCount_;
    int64_t tailCoreIndexCount_;
    int32_t usedCoreNum_;
    int64_t maxIndicesPerLoad_;
    int64_t inputStride0_;
    int64_t inputStride1_;
    int64_t oneUpdateAlignSize_;
    int64_t updateRowElements_;  // oneUpdateAlignSize_ / sizeof(T), UB中每行对齐后的元素数
};

// ======================== Implementation ========================

template <typename T, typename IndexT>
template <typename TilingDataT>
__aicore__ inline void ScatterBlockUpdateKernel<T, IndexT>::Init(
    GM_ADDR input, GM_ADDR indices, GM_ADDR update,
    const TilingDataT& tiling, TPipe* pipe)
{
    // 1. 绑定GlobalTensor
    inputGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(input));
    indicesGm_.SetGlobalBuffer(reinterpret_cast<__gm__ IndexT*>(indices));
    updateGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(update));

    // 2. 读取tiling参数
    updateDimSize_ = tiling.updateDimSize;
    eachCoreIndexCount_ = tiling.eachCoreIndexCount;
    tailCoreIndexCount_ = tiling.tailCoreIndexCount;
    usedCoreNum_ = tiling.usedCoreNum;
    maxIndicesPerLoad_ = tiling.maxIndicesPerLoad;
    inputStride0_ = tiling.inputStride0;
    inputStride1_ = tiling.inputStride1;

    int64_t oneIndexSize = tiling.oneIndexSize;
    oneUpdateAlignSize_ = tiling.oneUpdateAlignSize;
    updateRowElements_ = oneUpdateAlignSize_ / static_cast<int64_t>(sizeof(T));

    // 3. 初始化UB队列 (double buffer)
    pipe_ = pipe;
    if (maxIndicesPerLoad_ > 0) {
        pipe_->InitBuffer(indicesQue_, SCATTER_BUF_NUM,
                          static_cast<uint32_t>(maxIndicesPerLoad_ * oneIndexSize));
        pipe_->InitBuffer(updateQue_, SCATTER_BUF_NUM,
                          static_cast<uint32_t>(maxIndicesPerLoad_ * oneUpdateAlignSize_));
    }
}

template <typename T, typename IndexT>
__aicore__ inline void ScatterBlockUpdateKernel<T, IndexT>::Process()
{
    int32_t blockIdx = GetBlockIdx();
    if (blockIdx >= usedCoreNum_) {
        return;
    }

    int64_t coreStart = static_cast<int64_t>(blockIdx) * eachCoreIndexCount_;
    int64_t coreCount = (blockIdx == usedCoreNum_ - 1) ? tailCoreIndexCount_ : eachCoreIndexCount_;
    if (coreCount <= 0) {
        return;
    }

    int64_t processed = 0;
    int64_t remaining = coreCount;

    // double buffer队列自动排流水:
    // CopyIn的AllocTensor获取空闲slot, EnQue标记数据就绪;
    // ScatterOut的DeQue等待数据就绪, FreeTensor释放slot供下次CopyIn使用;
    // 两个buffer slot交替使用, MTE2与MTE3自然重叠
    while (remaining > 0) {
        int64_t loadCount = (remaining > maxIndicesPerLoad_) ? maxIndicesPerLoad_ : remaining;
        CopyIn(coreStart + processed, loadCount);
        ScatterOut(loadCount);
        processed += loadCount;
        remaining -= loadCount;
    }
}

template <typename T, typename IndexT>
__aicore__ inline void ScatterBlockUpdateKernel<T, IndexT>::CopyIn(
    int64_t startIdx, int64_t loadCount)
{
    LocalTensor<IndexT> indLocal = indicesQue_.AllocTensor<IndexT>();
    LocalTensor<T> updLocal = updateQue_.AllocTensor<T>();

    // 加载indices: loadCount行 × 2列, GM中连续存储, 整块32B对齐搬运
    int64_t indBytes = loadCount * INDICES_LAST_DIM * static_cast<int64_t>(sizeof(IndexT));
    DataCopyExtParams indicesCopyParams;
    indicesCopyParams.blockCount = 1;
    indicesCopyParams.blockLen = static_cast<uint32_t>(indBytes);
    indicesCopyParams.srcStride = 0;
    indicesCopyParams.dstStride = 0;
    DataCopyPadExtParams<IndexT> indicesPadParams{false, 0, 0, 0};
    DataCopyPad(indLocal, indicesGm_[startIdx * INDICES_LAST_DIM], indicesCopyParams, indicesPadParams);

    // 加载updates
    // 用DataCopyPad按行加载, 每行在UB中padding到oneUpdateAlignSize_字节
    // 保证ScatterOut中 updLocal[i * updateRowElements_] 取子视图时偏移32B对齐
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(loadCount);
    copyParams.blockLen = static_cast<uint32_t>(updateDimSize_ * static_cast<int64_t>(sizeof(T)));
    copyParams.srcStride = 0;  // GM中行连续, 无间隔
    copyParams.dstStride = 0;  // UB行间padding
    DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
    DataCopyPad(updLocal, updateGm_[startIdx * updateDimSize_], copyParams, padParams);

    indicesQue_.EnQue(indLocal);
    updateQue_.EnQue(updLocal);
}

template <typename T, typename IndexT>
__aicore__ inline void ScatterBlockUpdateKernel<T, IndexT>::ScatterOut(
    int64_t loadCount)
{
    // DeQue等待MTE2加载完成
    LocalTensor<IndexT> indLocal = indicesQue_.DeQue<IndexT>();
    LocalTensor<T> updLocal = updateQue_.DeQue<T>();
    event_t eventIdMTE2ToS = static_cast<event_t>(GetTPipePtr()->AllocEventID<HardEvent::MTE2_S>());
    SetFlag<HardEvent::MTE2_S>(eventIdMTE2ToS);
    WaitFlag<HardEvent::MTE2_S>(eventIdMTE2ToS);
    for (int64_t i = 0; i < loadCount; i++) {
        // 读取索引对 (idx0, idx1)
        IndexT idx0 = indLocal.GetValue(static_cast<uint32_t>(i * INDICES_LAST_DIM));
        IndexT idx1 = indLocal.GetValue(static_cast<uint32_t>(i * INDICES_LAST_DIM + 1));
        if (idx0 < 0 || idx1 < 0) {
            continue;
        }
        // 根据stride计算GM中目标行的元素偏移
        // offset = idx0 * stride0 + idx1 * stride1
        int64_t gmOffset = static_cast<int64_t>(idx0) * inputStride0_ +
                           static_cast<int64_t>(idx1) * inputStride1_;

        // D > 1 且 D*sizeof(T) 32B对齐: DataCopy整行搬出
        // updLocal[i * updateRowElements_] 偏移32B对齐 (DataCopyPad保证)
        DataCopyExtParams copyParams;
        copyParams.blockCount = static_cast<uint16_t>(1);
        copyParams.blockLen = static_cast<uint32_t>(updateDimSize_ * static_cast<int64_t>(sizeof(T)));
        copyParams.srcStride = 0;
        copyParams.dstStride = 0;
        DataCopyPad(inputGm_[gmOffset], updLocal[static_cast<uint32_t>(i * updateRowElements_)], copyParams);
    }
    indicesQue_.FreeTensor(indLocal);
    updateQue_.FreeTensor(updLocal);
}

#endif // __AI_INFRA_SCATTER_BLOCK_UPDATE_KERNEL_H__

